// Content with portions generated by generative AI platform
package org.eclipse.kura.container.orchestration.provider.impl.enforcement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.doAnswer;

import java.util.Collections;

import org.eclipse.kura.KuraException;
import org.junit.Test;

public class EnforcementCloseTest extends AbstractEnforcementTest {

    private RuntimeException closeFailure;
    private RuntimeException startFailure;

    @Test
    public void startEnforcingReturnsWhenCloseDropsTheStartupSweep() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenEnforcementClosedWhileStartEnforcingWaits();

        whenEnforcementStartsCapturingFailures();

        thenStartEnforcingReturnedWithoutError();
        thenNoContainerWasDeleted();
    }

    @Test
    public void sweepQueuedBeforeCloseNeverRuns() throws KuraException {
        givenRunningContainer(CONTAINER_ID, IMAGE_DIGEST);
        givenDigestRegisteredBy(CONTAINER_ID, IMAGE_DIGEST);
        givenStartedEnforcement();
        givenDigestUnregisteredBy(CONTAINER_ID);
        givenClosedEnforcement();

        whenSchedulerRunsPendingTasks();

        thenContainersWereListed(1);
        thenNoContainerWasDeleted();
    }

    @Test
    public void retryScheduledBeforeCloseNeverSweeps() {
        givenContainerListingFails();
        givenStartedEnforcement();
        givenClosedEnforcement();

        whenScheduledDelayElapses();

        thenContainersWereListed(1);
    }

    @Test
    public void closingAfterTheEventStreamFailedRaisesNoError() {
        givenStartedEnforcement();
        givenEventStreamFailed();

        whenEnforcementCloses();

        thenCloseRaisedNoError();
    }

    @Test
    public void restartScheduledBeforeCloseNeverSubscribes() {
        givenStartedEnforcement();
        givenEventStreamFailed();
        givenClosedEnforcement();

        whenScheduledDelayElapses();

        thenEventsWereSubscribed(1);
    }

    @Test
    public void sweepFailingAfterCloseSchedulesNoRetry() {
        givenContainerListingClosesEnforcementAndFails();

        whenEnforcementStarts();

        thenNothingWasScheduled();
        thenNoSchedulerTaskFailed();
    }

    @Test
    public void streamConnectingAfterCloseIsClosed() {
        givenEventStreamConnectsLate();
        givenStartedEnforcement();
        givenClosedEnforcement();

        whenEventStreamConnects();

        thenEventStreamWasClosed();
    }

    @Test
    public void eventsFromAStreamConnectingAfterCloseAreIgnored() throws KuraException {
        givenContainerWithImageDigest(OTHER_CONTAINER_ID, IMAGE_DIGEST);
        givenEventStreamConnectsLate();
        givenStartedEnforcement();
        givenClosedEnforcement();
        givenEventStreamConnected();

        whenStartEventArrivesFor(OTHER_CONTAINER_ID);

        thenNoContainerWasDeleted();
    }

    private void givenEnforcementClosedWhileStartEnforcingWaits() {
        this.scheduler.whileAwaitingASubmittedTask(this.enforcement::close);
    }

    private void givenContainerListingClosesEnforcementAndFails() {
        doAnswer(invocation -> {
            this.enforcement.close();
            throw new IllegalStateException("docker unreachable");
        }).when(this.target).listContainerDescriptors();
    }

    private void givenEventStreamConnected() {
        this.events.connectDelayedStream();
    }

    private void whenEnforcementStartsCapturingFailures() {
        try {
            this.enforcement.startEnforcing(EMPTY_ALLOWLIST, this.events.client());
        } catch (RuntimeException e) {
            this.startFailure = e;
        }
    }

    private void whenEnforcementCloses() {
        try {
            this.enforcement.close();
        } catch (RuntimeException e) {
            this.closeFailure = e;
        }
    }

    private void whenEventStreamConnects() {
        this.events.connectDelayedStream();
    }

    private void thenStartEnforcingReturnedWithoutError() {
        assertNull("startEnforcing did not return: " + this.startFailure, this.startFailure);
    }

    private void thenCloseRaisedNoError() {
        assertNull(this.closeFailure);
    }

    private void thenEventStreamWasClosed() {
        assertTrue(this.events.latestStreamWasClosed());
    }

    private void thenNoSchedulerTaskFailed() {
        assertEquals(Collections.emptyList(), this.scheduler.taskFailures());
    }
}
